:root {
  --ink: #eaf7ff;
  --muted: #7590ad;
  --cyan: #38f2ff;
  --cyan-soft: rgba(56, 242, 255, 0.18);
  --pink: #ff2e88;
  --amber: #ffc857;
  --danger: #ff4968;
  --panel: rgba(7, 12, 25, 0.68);
  --line: rgba(118, 218, 255, 0.18);
  --mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Consolas, monospace;
  --display: "Arial Narrow", "Roboto Condensed", "Helvetica Neue", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #05060f;
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}

button { font: inherit; color: inherit; }

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #05060f;
}

#ui {
  position: fixed;
  inset: 0;
  pointer-events: none;
  padding:
    calc(18px + env(safe-area-inset-top))
    calc(22px + env(safe-area-inset-right))
    calc(20px + env(safe-area-inset-bottom))
    calc(24px + env(safe-area-inset-left));
  z-index: 10;
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--cyan);
  filter: drop-shadow(0 0 14px rgba(56, 242, 255, 0.45));
}

.brand-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(56, 242, 255, 0.4);
  background: linear-gradient(150deg, rgba(56, 242, 255, 0.15), rgba(56, 242, 255, 0.01));
  clip-path: polygon(0 0, 100% 0, 100% 74%, 74% 100%, 0 100%);
}

.brand-mark svg { width: 25px; height: 25px; }

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 0.86;
  letter-spacing: 0.12em;
}

.brand-copy b {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.brand-copy i {
  font-style: normal;
  font-family: var(--mono);
  font-size: 9px;
  color: #8be9ff;
  letter-spacing: 0.52em;
  margin-top: 5px;
  text-shadow: none;
}

.top-actions {
  display: flex;
  align-items: stretch;
  gap: 9px;
  pointer-events: auto;
}

.best-chip,
.sound-btn,
.pause-btn {
  position: relative;
  height: 52px;
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(24, 38, 63, 0.62), rgba(6, 11, 24, 0.74));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 10px 34px rgba(0, 0, 0, 0.35);
}

.best-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px 0 13px;
  min-width: 128px;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 10px 100%, 0 calc(100% - 10px));
}

.best-icon {
  color: var(--amber);
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 0 8px rgba(255, 200, 87, 0.45));
}

.best-icon svg { width: 23px; height: 23px; }

.best-meta { display: flex; flex-direction: column; gap: 2px; }

.best-meta em {
  font-style: normal;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.26em;
  color: #9aacbf;
}

.best-meta strong {
  font-family: var(--mono);
  font-size: 19px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: #fff2ce;
  font-variant-numeric: tabular-nums;
}

.sound-btn {
  width: 48px;
  display: grid;
  place-items: center;
  cursor: pointer;
  color: #94aec5;
  transition: color 160ms ease, border-color 160ms ease, background 160ms ease;
}

.sound-btn svg { width: 20px; height: 20px; }
.sound-btn .sound-off { display: none; }
body.muted .sound-btn .sound-on { display: none; }
body.muted .sound-btn .sound-off { display: block; }
.sound-btn:hover { color: var(--cyan); border-color: rgba(56, 242, 255, 0.5); }

.pause-btn {
  min-width: 122px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 18px;
  cursor: pointer;
  color: #dff9ff;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.22em;
  border-color: rgba(56, 242, 255, 0.32);
  clip-path: polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 0 100%);
  transition: background 170ms ease, color 170ms ease, border-color 170ms ease, transform 170ms ease;
}

.pause-btn:hover {
  background: linear-gradient(180deg, rgba(34, 87, 110, 0.75), rgba(8, 26, 38, 0.85));
  border-color: rgba(56, 242, 255, 0.7);
  color: #fff;
}

.pause-btn:active { transform: translateY(1px); }

.pause-glyph {
  display: flex;
  gap: 3px;
  align-items: center;
  justify-content: center;
}

.pause-glyph i {
  display: block;
  width: 3px;
  height: 12px;
  background: currentColor;
  box-shadow: 0 0 8px rgba(56, 242, 255, 0.6);
}

body.paused .pause-glyph i {
  width: 0; height: 0;
  background: transparent;
  border-top: 7px solid transparent;
  border-bottom: 7px solid transparent;
  border-left: 10px solid currentColor;
  box-shadow: none;
}

body.paused .pause-glyph { gap: 0; }

body.paused .pause-btn {
  border-color: rgba(255, 200, 87, 0.55);
  color: #ffe6a9;
}

.score-stack {
  position: absolute;
  top: calc(94px + env(safe-area-inset-top));
  left: calc(24px + env(safe-area-inset-left));
  width: min(310px, 48vw);
}

.kicker {
  display: block;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.36em;
  color: #829bb1;
}

.score-line {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  margin-top: 1px;
}

#scoreValue {
  font-family: var(--display);
  font-size: clamp(36px, 5vw, 54px);
  font-weight: 800;
  line-height: 0.94;
  letter-spacing: 0.02em;
  color: #f2fdff;
  text-shadow:
    0 0 12px rgba(56, 242, 255, 0.35),
    0 3px 0 rgba(0, 32, 48, 0.5);
  font-variant-numeric: tabular-nums;
}

.multiplier {
  margin-bottom: 7px;
  padding: 4px 8px 3px;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 800;
  color: #07101a;
  background: var(--cyan);
  box-shadow: 0 0 18px rgba(56, 242, 255, 0.45);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 6px), calc(100% - 6px) 100%, 0 100%);
  transition: transform 140ms ease, background 140ms ease;
}

.multiplier.hot {
  background: var(--pink);
  color: #fff;
  box-shadow: 0 0 22px rgba(255, 46, 136, 0.62);
  transform: scale(1.08);
}

.combo-track {
  width: 136px;
  height: 2px;
  margin-top: 8px;
  background: rgba(56, 242, 255, 0.14);
  overflow: hidden;
}

.combo-track i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  background: linear-gradient(90deg, var(--cyan), #93ffe7);
  box-shadow: 0 0 10px rgba(56, 242, 255, 0.8);
}

.heat-stack {
  position: absolute;
  top: calc(94px + env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
}

.heat-stars {
  display: flex;
  gap: 5px;
  margin-top: 5px;
  filter: drop-shadow(0 0 9px rgba(255, 73, 104, 0.45));
}

.heat-stars i {
  width: 14px;
  height: 14px;
  display: block;
  background: rgba(120, 142, 165, 0.1);
  clip-path: polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 94%, 50% 72%, 21% 94%, 32% 57%, 2% 35%, 39% 35%);
  transition: background 250ms ease;
}

.heat-stars i.on {
  background: linear-gradient(180deg, #ffb15c, #ff2e6d);
}

.heat-stars i.pulse { animation: star-pulse 1.6s ease-in-out infinite; }

@keyframes star-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

.status-stack {
  position: absolute;
  left: calc(24px + env(safe-area-inset-left));
  bottom: calc(22px + env(safe-area-inset-bottom));
  width: min(310px, 54vw);
}

.hull-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.hull-row .kicker { min-width: 32px; }

.hull-track {
  position: relative;
  flex: 1;
  height: 7px;
  padding: 1px;
  background: rgba(91, 116, 140, 0.18);
  border: 1px solid rgba(158, 187, 214, 0.14);
  transform: skewX(-18deg);
  overflow: hidden;
}

.hull-track i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  background: linear-gradient(90deg, #20d6a8, #79ffd5);
