import { BLOCK, ROAD, BASES, ACCENTS, clamp, mulberry32 } from './config.js';

const blockCache = new Map();

function makeBuilding(rx, ry, rw, rh, rng) {
  const inset = 5 + rng() * 8;
  const x = rx + inset;
  const y = ry + inset;
  const w = rw - inset * 2;
  const h = rh - inset * 2;
  if (w < 18 || h < 18) return null;

  const base = BASES[Math.floor(rng() * BASES.length)];
  const accent = ACCENTS[Math.floor(rng() * ACCENTS.length)];
  const cols = clamp(Math.floor(w / (18 + rng() * 9)), 2, 9);
  const rows = clamp(Math.floor(h / (20 + rng() * 10)), 2, 11);
  const windows = new Uint8Array(cols * rows);
  for (let i = 0; i < windows.length; i++) {
    const roll = rng();
    windows[i] = roll < 0.52 ? 0 : roll < 0.72 ? 1 : roll < 0.88 ? 2 : 3;
  }

  const sign = rng() < 0.58 ? {
    side: rng() < 0.5 ? -1 : 1,
    color: rng() < 0.55 ? accent : ACCENTS[Math.floor(rng() * ACCENTS.length)],
    offset: 0.12 + rng() * 0.2,
    length: 0.24 + rng() * 0.42
  } : null;

  const roofs = [];
  const roofCount = Math.floor(rng() * 3);
  for (let i = 0; i < roofCount; i++) {
    const bw = Math.min(w * 0.32, 24 + rng() * 34);
    const bh = Math.min(h * 0.32, 18 + rng() * 28);
    roofs.push({
      x: x + (w - bw) * (0.2 + rng() * 0.6),
      y: y + (h - bh) * (0.2 + rng() * 0.6),
      w: bw,
      h: bh
    });
  }

  return {
    x, y, w, h, base, accent, cols, rows, windows, sign, roofs,
    neon: rng() < 0.74,
    antenna: rng() < 0.17,
    seed: Math.floor(rng() * 10000)
  };
}

export function getBlock(bx, by) {
  const key = `${bx},${by}`;
  const cached = blockCache.get(key);
  if (cached) return cached;

  const rng = mulberry32(((bx * 73856093) ^ (by * 19349663) ^ 0x9e3779b9) >>> 0);
  const x0 = bx * BLOCK + ROAD / 2;
  const y0 = by * BLOCK + ROAD / 2;
  const size = BLOCK - ROAD;
  const gap = 11 + rng() * 18;
  const mode = rng();
  const regions = [];

  if (mode < 0.3) {
    regions.push([x0, y0, size, size]);
  } else if (mode < 0.59) {
    const split = size * (0.38 + rng() * 0.24);
    regions.push([x0, y0, split - gap / 2, size], [x0 + split + gap / 2, y0, size - split - gap / 2, size]);
  } else if (mode < 0.85) {
    const split = size * (0.38 + rng() * 0.24);
    regions.push([x0, y0, size, split - gap / 2], [x0, y0 + split + gap / 2, size, size - split - gap / 2]);
  } else {
    const sx = size * (0.4 + rng() * 0.2);
    const sy = size * (0.4 + rng() * 0.2);
    regions.push(
      [x0, y0, sx - gap / 2, sy - gap / 2],
      [x0 + sx + gap / 2, y0, size - sx - gap / 2, sy - gap / 2],
      [x0, y0 + sy + gap / 2, sx - gap / 2, size - sy - gap / 2],
      [x0 + sx + gap / 2, y0 + sy + gap / 2, size - sx - gap / 2, size - sy - gap / 2]
    );
  }

  const rects = [];
  for (const region of regions) {
    if (rng() < 0.06) continue;
    const building = makeBuilding(region[0], region[1], region[2], region[3], rng);
    if (building) rects.push(building);
  }

  const block = { x0, y0, size, rects };
  blockCache.set(key, block);
  return block;
}

export function findBuildingPush(x, y, radius) {
  const bx = Math.floor(x / BLOCK);
  const by = Math.floor(y / BLOCK);
  for (let ox = -1; ox <= 1; ox++) {
    for (let oy = -1; oy <= 1; oy++) {
      const block = getBlock(bx + ox, by + oy);
      for (const b of block.rects) {
        if (x > b.x && x < b.x + b.w && y > b.y && y < b.y + b.h) {
          const left = x - b.x;
          const right = b.x + b.w - x;
          const top = y - b.y;
          const bottom = b.y + b.h - y;
          const min = Math.min(left, right, top, bottom);
          if (min === left) return { nx: -1, ny: 0, depth: left + radius };
          if (min === right) return { nx: 1, ny: 0, depth: right + radius };
          if (min === top) return { nx: 0, ny: -1, depth: top + radius };
          return { nx: 0, ny: 1, depth: bottom + radius };
        }
        const nx = x < b.x ? b.x : x > b.x + b.w ? b.x + b.w : x;
        const ny = y < b.y ? b.y : y > b.y + b.h ? b.y + b.h : y;
        const dx = x - nx;
        const dy = y - ny;
        const distSq = dx * dx + dy * dy;
        if (distSq < radius * radius) {
          const dist = Math.sqrt(distSq) || 0.001;
          return { nx: dx / dist, ny: dy / dist, depth: radius - dist };
        }
      }
    }
  }
  return null;
}

export function pointBlocked(x, y, radius) {
  return findBuildingPush(x, y, radius) !== null;
}

import { loadMuted, saveMuted } from './config.js';

export const audio = {
  ctx: null,
  master: null,
  engineGain: null,
  engineFilter: null,
  osc1: null,
  osc2: null,
  noiseBuffer: null,
  enabled: !loadMuted(),

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return true;
    }
    const AudioCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtor) return false;
    try {
      const ctx = this.ctx = new AudioCtor();
      this.master = ctx.createGain();
      this.master.gain.value = this.enabled ? 0.62 : 0;
      this.master.connect(ctx.destination);

      this.engineFilter = ctx.createBiquadFilter();
      this.engineFilter.type = 'lowpass';
      this.engineFilter.frequency.value = 240;
      this.engineFilter.Q.value = 1.1;

      this.engineGain = ctx.createGain();
      this.engineGain.gain.value = 0;
      this.engineFilter.connect(this.engineGain);
      this.engineGain.connect(this.master);

      const makeOsc = (frequency, type, level) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = type;
        osc.frequency.value = frequency;
        gain.gain.value = level;
        osc.connect(gain);
        gain.connect(this.engineFilter);
        osc.start();
        return osc;
      };
      this.osc1 = makeOsc(52, 'sawtooth', 0.5);
      this.osc2 = makeOsc(78, 'square', 0.12);

      const length = Math.floor(ctx.sampleRate * 0.4);
      const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
      this.noiseBuffer = buffer;

      if (ctx.state === 'suspended') ctx.resume().catch(() => {});
      return true;
    } catch {
      return false;
    }
  },

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
  },

  setMuted(muted) {
    this.enabled = !muted;
    saveMuted(muted);
    document.body.classList.toggle('muted', muted);
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.62, this.ctx.currentTime, 0.04);
    }
  },

  update(speed, active) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    this.engineGain.gain.setTargetAtTime(active ? 0.038 : 0, now, 0.12);
    if (!active) return;
    const frequency = 40 + Math.min(speed, 760) * 0.115;
    this.osc1.frequency.setTargetAtTime(frequency, now, 0.12);
    this.osc2.frequency.setTargetAtTime(frequency * 1.51, now, 0.12);
    this.engineFilter.frequency.setTargetAtTime(190 + Math.min(speed, 760) * 0.52, now, 0.12);
  },

  tone(startFrequency, endFrequency, duration, type = 'sine', volume = 0.05) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(1, startFrequency), now);
    osc.frequency.exponentialRampToValueAtTime(Math.max(1, endFrequency), now + duration);
    gain.gain.setValueAtTime(volume, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + duration + 0.02);
  },

  pickup() {
    this.tone(680, 1180, 0.14, 'sine', 0.055);
    window.setTimeout(() => this.tone(1180, 1540, 0.1, 'sine', 0.035), 55);
  },

  nearMiss() {
    this.tone(220, 90, 0.16, 'sawtooth', 0.024);
  },

  crash() {
    if (!this.ctx || !this.enabled || !this.noiseBuffer) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const source = ctx.createBufferSource();
    const filter = ctx.createBiquadFilter();
    const gain = ctx.createGain();
    source.buffer = this.noiseBuffer;
    filter.type = 'lowpass';
    filter.frequency.value = 900;
    gain.gain.setValueAtTime(0.16, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.28);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    source.start(now);
    source.stop(now + 0.3);
    this.tone(120, 44, 0.24, 'triangle', 0.09);
  },

  siren() {
    this.tone(720, 470, 0.18, 'square', 0.018);
    window.setTimeout(() => this.tone(500, 760, 0.18, 'square', 0.018), 170);
  },

  levelUp() {
    this.tone(320, 520, 0.16, 'triangle', 0.05);
    window.setTimeout(() => this.tone(520, 760, 0.18, 'triangle', 0.04), 90);
  }
};

import { fmt, clamp } from './config.js';
import { state, hud } from './state.js';
import { audio } from './audio.js';

export const dom = {
  canvas: document.getElementById('game'),
  score: document.getElementById('scoreValue'),
  best: document.getElementById('bestValue'),
  bestChip: document.querySelector('.best-chip'),
  multiplier: document.getElementById('multiplier'),
