export function drawParticles() {
  if (!state.particles.length) return;
  ctx.save();
  for (const particle of state.particles) {
    const alpha = Math.max(0, particle.life / particle.max) * particle.alpha;
    if (alpha <= 0) continue;
    if (particle.type === 'smoke') {
      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = alpha * 0.36;
      ctx.fillStyle = '#56657f';
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, particle.size * (1 + (1 - particle.life / particle.max) * 2.2), 0, Math.PI * 2);
      ctx.fill();
    } else if (particle.type === 'trail') {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = alpha;
      ctx.fillStyle = particle.color;
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, Math.max(0.5, particle.size * alpha), 0, Math.PI * 2);
      ctx.fill();
    } else if (particle.type === 'spark') {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = alpha;
      ctx.strokeStyle = particle.color;
      ctx.lineWidth = Math.max(0.6, particle.size * alpha);
      ctx.beginPath();
      ctx.moveTo(particle.x, particle.y);
      ctx.lineTo(particle.x - particle.vx * 0.024, particle.y - particle.vy * 0.024);
      ctx.stroke();
    } else {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = alpha;
      ctx.fillStyle = particle.color;
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

import { BLOCK, TAU, clamp } from './config.js';
import { state } from './state.js';
import { drawCity, bindCityContext } from './draw-city.js';
import { drawTrafficCar, drawPoliceCar, drawPlayerCar, drawParticles, bindCarContext } from './draw-cars.js';

let ctx = null;
let W = 1;
let H = 1;
let DPR = 1;

export function initRender(context, width, height, dpr) {
  ctx = context;
  W = width;
  H = height;
  DPR = dpr;
  bindCityContext(ctx);
  bindCarContext(ctx);
}

export function resizeRender(width, height, dpr) {
  W = width;
  H = height;
  DPR = dpr;
}

function worldToScreen(x, y) {
  const cam = state.cam;
  const theta = -cam.angle - Math.PI / 2;
  const cos = Math.cos(theta);
  const sin = Math.sin(theta);
  const dx = x - cam.x;
  const dy = y - cam.y;
  return {
    x: W / 2 + (dx * cos - dy * sin) * cam.zoom,
    y: H / 2 + (dx * sin + dy * cos) * cam.zoom
  };
}

export function render(now, dt) {
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  ctx.fillStyle = '#04060e';
  ctx.fillRect(0, 0, W, H);

  const cam = state.cam;
  const shake = cam.shake;
  const shakeX = shake > 0.1 ? (Math.random() * 2 - 1) * shake * 0.55 : 0;
  const shakeY = shake > 0.1 ? (Math.random() * 2 - 1) * shake * 0.55 : 0;

  const radius = Math.hypot(W, H) / 2 / cam.zoom + 320;
  const view = {
    minX: cam.x - radius,
    maxX: cam.x + radius,
    minY: cam.y - radius,
    maxY: cam.y + radius,
    minBX: Math.floor((cam.x - radius) / BLOCK) - 1,
    maxBX: Math.ceil((cam.x + radius) / BLOCK) + 1,
    minBY: Math.floor((cam.y - radius) / BLOCK) - 1,
    maxBY: Math.ceil((cam.y + radius) / BLOCK) + 1
  };

  ctx.save();
  ctx.translate(W / 2 + shakeX, H / 2 + shakeY);
  ctx.scale(cam.zoom, cam.zoom);
  ctx.rotate(-cam.angle - Math.PI / 2);
  ctx.translate(-cam.x, -cam.y);

  drawCity(view, now);
  for (const car of state.traffic) drawTrafficCar(car);
  for (const car of state.police) drawPoliceCar(car, now);
  if (!state.over || Math.sin(now * 0.03) > -0.2) drawPlayerCar(now);
  drawParticles();

  ctx.restore();

  drawFloaters();
  drawRain(dt);
  drawSpeedFx(now);
  drawAtmosphere(now);
}

function drawFloaters() {
  if (!state.floaters.length) return;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const floater of state.floaters) {
    const progress = 1 - floater.life / floater.max;
    const pos = worldToScreen(floater.x, floater.y);
    const alpha = clamp(floater.life * 1.7, 0, 1);
    ctx.globalAlpha = alpha;
    ctx.font = `700 ${floater.size}px "SFMono-Regular", "Cascadia Mono", Consolas, monospace`;
    ctx.fillStyle = floater.color;
    ctx.shadowColor = floater.color;
    ctx.shadowBlur = 9;
    ctx.fillText(floater.text, pos.x, pos.y - progress * 34);
  }
  ctx.restore();
}

function drawRain(dt) {
  if (!state.rain.length) return;
  const drops = state.rain;
  for (const drop of drops) {
    if (dt > 0) {
      drop.y += drop.speed * dt;
      drop.x -= drop.speed * 0.12 * dt;
      if (drop.y > H + 24) {
        drop.y = -24 - Math.random() * 90;
        drop.x = Math.random() * (W + 80);
      }
      if (drop.x < -30) drop.x = W + 20;
    }
  }
  ctx.save();
  ctx.strokeStyle = 'rgba(157,207,255,0.13)';
  ctx.lineWidth = 0.75;
  ctx.beginPath();
  for (const drop of drops) {
    ctx.moveTo(drop.x, drop.y);
    ctx.lineTo(drop.x + drop.length * 0.12, drop.y + drop.length);
  }
  ctx.stroke();
  ctx.restore();
}

function drawSpeedFx(now) {
  const speed = Math.hypot(state.player.vx, state.player.vy);
  const intensity = clamp((speed - 410) / 300, 0, 1);
  if (intensity <= 0.01) return;
  const cx = W / 2;
  const cy = H / 2;
  const minDim = Math.min(W, H);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 18; i++) {
    const angle = (i / 18) * TAU + Math.sin(now * 0.0004 + i * 1.7) * 0.02;
    const start = minDim * (0.34 + ((i * 13) % 11) * 0.018);
    const length = 55 + intensity * 115;
    ctx.strokeStyle = `rgba(86,215,255,${0.018 + intensity * 0.055})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(angle) * start, cy + Math.sin(angle) * start);
    ctx.lineTo(cx + Math.cos(angle) * (start + length), cy + Math.sin(angle) * (start + length));
    ctx.stroke();
  }
  ctx.restore();
}

function drawAtmosphere(now) {
  const edge = ctx.createLinearGradient(0, 0, 0, H);
  edge.addColorStop(0, 'rgba(28,170,255,0.045)');
  edge.addColorStop(0.23, 'rgba(0,0,0,0)');
  edge.addColorStop(0.76, 'rgba(0,0,0,0)');
  edge.addColorStop(1, 'rgba(255,46,136,0.05)');
  ctx.fillStyle = edge;
  ctx.fillRect(0, 0, W, H);

  const vignette = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.24, W / 2, H / 2, Math.max(W, H) * 0.76);
  vignette.addColorStop(0, 'rgba(2,4,12,0)');
  vignette.addColorStop(0.72, 'rgba(2,4,12,0.16)');
  vignette.addColorStop(1, 'rgba(1,3,9,0.78)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, W, H);

  if (state.health <= 34 && !state.over) {
    const pulse = 0.55 + Math.sin(now * 0.006) * 0.25;
    const red = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.3, W / 2, H / 2, Math.max(W, H) * 0.7);
    red.addColorStop(0, 'rgba(255,30,70,0)');
    red.addColorStop(1, `rgba(255,25,65,${0.16 * pulse})`);
    ctx.fillStyle = red;
    ctx.fillRect(0, 0, W, H);
  }

  if (state.flash > 0.01) {
    ctx.fillStyle = `rgba(255,42,84,${state.flash * 0.2})`;
    ctx.fillRect(0, 0, W, H);
  }
}

import { BLOCK, ROAD, TAU, MAX_TRAFFIC, MAX_PICKUPS, TRAFFIC_COLORS, clamp, saveBest } from './config.js';
import { state, resetWorld } from './state.js';
import { pointBlocked } from './city.js';
import { audio } from './audio.js';
import * as ui from './ui.js';

export function addParticle(x, y, vx, vy, life, size, color, type = 'spark', alpha = 1) {
  if (state.particles.length > 460) state.particles.shift();
  state.particles.push({ x, y, vx, vy, life, max: life, size, color, type, alpha });
}

export function addFloater(x, y, text, color, size = 12) {
  if (state.floaters.length > 16) state.floaters.shift();
  state.floaters.push({ x, y, text, color, size, life: 1.15, max: 1.15 });
}

export function burst(x, y, color, count = 16, speed = 190) {
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * TAU;
    const velocity = speed * (0.35 + Math.random() * 0.8);
    addParticle(
      x, y,
      Math.cos(angle) * velocity,
      Math.sin(angle) * velocity,
      0.28 + Math.random() * 0.42,
      1.2 + Math.random() * 2,
      color,
      'spark',
      0.9
    );
  }
}

function smoke(x, y, count = 5) {
  for (let i = 0; i < count; i++) {
    addParticle(
      x + (Math.random() - 0.5) * 20,
      y + (Math.random() - 0.5) * 20,
      (Math.random() - 0.5) * 44,
      (Math.random() - 0.5) * 44 - 14,
      0.7 + Math.random() * 0.8,
      5 + Math.random() * 8,
      '#56657f',
      'smoke',
      0.7
    );
  }
}

function roadSpot(minDistance, maxDistance, avoidRadius, ahead, forPickup) {
  const p = state.player;
  for (let attempt = 0; attempt < 44; attempt++) {
    const angle = ahead
      ? p.angle + (Math.random() - 0.5) * 2.35
      : Math.random() * TAU;
    const distance = minDistance + Math.random() * (maxDistance - minDistance);
    let x = p.x + Math.cos(angle) * distance;
    let y = p.y + Math.sin(angle) * distance;

    const roadX = Math.round(x / BLOCK) * BLOCK;
    const roadY = Math.round(y / BLOCK) * BLOCK;
    let heading = -Math.PI / 2;
    const vertical = Math.abs(x - roadX) <= Math.abs(y - roadY);
    if (vertical) {
      if (forPickup) {
        x = roadX + (Math.random() < 0.5 ? -1 : 1) * ROAD * 0.19;
      } else {
        const up = Math.random() < 0.5;
        heading = up ? -Math.PI / 2 : Math.PI / 2;
        x = roadX + (up ? 1 : -1) * ROAD * 0.21;
      }
    } else if (forPickup) {
      y = roadY + (Math.random() < 0.5 ? -1 : 1) * ROAD * 0.19;
    } else {
      const right = Math.random() < 0.5;
      heading = right ? 0 : Math.PI;
      y = roadY + (right ? 1 : -1) * ROAD * 0.21;
    }

    if (Math.hypot(x - p.x, y - p.y) < avoidRadius) continue;
    if (pointBlocked(x, y, 26)) continue;
    return { x, y, angle: heading };
  }
  return null;
}

export function spawnTraffic(initial = false) {
  if (state.traffic.length >= MAX_TRAFFIC) return;
  const spot = roadSpot(initial ? 280 : 640, initial ? 1180 : 1420, 250, false, false);
  if (!spot) return;
  if (state.traffic.some((car) => Math.hypot(car.x - spot.x, car.y - spot.y) < 72)) return;
  const colors = TRAFFIC_COLORS[Math.floor(Math.random() * TRAFFIC_COLORS.length)];
  state.traffic.push({
    x: spot.x,
    y: spot.y,
    angle: spot.angle,
    speed: 96 + Math.random() * 94,
    color: colors[0],
    dark: colors[1],
    near: false,
    seed: Math.random() * 1000
  });
}

export function spawnPickup(initial = false) {
  if (state.pickups.length >= MAX_PICKUPS) return;
  const spot = roadSpot(initial ? 330 : 360, initial ? 1050 : 920, 180, true, true);
  if (!spot) return;
  if (state.pickups.some((pickup) => Math.hypot(pickup.x - spot.x, pickup.y - spot.y) < 95)) return;
  state.pickups.push({
    x: spot.x,
    y: spot.y,
    phase: Math.random() * TAU,
    seed: Math.random() * 100
  });
}

export function spawnPolice(initial = false) {
  const p = state.player;
  let x;
  let y;
  let angle = -Math.PI / 2;
  if (initial) {
    x = p.x;
    y = p.y + 270;
  } else {
    const side = Math.random() * TAU;
    const distance = 700 + Math.random() * 280;
    x = p.x + Math.cos(side) * distance;
    y = p.y + Math.sin(side) * distance;
    angle = -Math.PI / 2 + (Math.random() - 0.5);
  }
  state.police.push({
    x,
    y,
    angle,
    speed: initial ? 285 : 250,
    maxSpeed: 302 + state.heat * 18 + Math.random() * 20,
    seed: Math.random() * TAU
  });
}

export function startRun(isRestart = false) {
  state.runId++;
  state.paused = false;
  state.over = false;
  state.overShown = false;
  state.time = 0;
  state.score = 0;
  state.distance = 0;
  state.health = 100;
  state.heat = 1;
  state.multiplier = 1;
  state.comboTimer = 0;
  state.recordBeaten = false;
  state.damageCooldown = 0;
  state.flash = 0;
  state.spawnTimer = 0.9;
  state.policeSpawnTimer = 4;
  state.sirenTimer = 2.5;

  resetWorld();
  for (let i = 0; i < 14; i++) spawnTraffic(true);
  for (let i = 0; i < MAX_PICKUPS; i++) spawnPickup(true);
  spawnPolice(true);

  ui.hideOverlays();
  ui.hideToast();
  ui.updateHud(true);
  if (isRestart) ui.hideHint();
  else ui.showHint();
  audio.update(0, true);
}

export function restartRun() {
  startRun(true);
}

export function togglePause(force) {
  if (state.over) return;
  const next = typeof force === 'boolean' ? force : !state.paused;
  if (next === state.paused) return;
  state.paused = next;
  ui.setPausedUI(next);
  if (next) {
    audio.update(0, false);
  } else {
    audio.resume();
  }
}

export function endRun() {
  if (state.over) return;
  state.over = true;
  state.paused = false;
  state.health = 0;
  state.player.vx = 0;
  state.player.vy = 0;
  state.multiplier = 1;
  state.comboTimer = 0;

  const x = state.player.x;
  const y = state.player.y;
  burst(x, y, '#ffd166', 34, 300);
  burst(x, y, '#ff4f77', 26, 240);
  smoke(x, y, 14);
  state.cam.shake = 32;
  state.flash = 0.95;
  audio.crash();
  ui.hideHint();

  const score = Math.floor(state.score);
  const isNewRecord = score > state.best && score > 0;
  if (isNewRecord) {
    state.best = score;
    state.recordBeaten = true;
    saveBest(score);
  }
  ui.updateHud(true);

  const runId = state.runId;
  window.setTimeout(() => {
    if (state.runId === runId && state.over) ui.showGameOver(score, isNewRecord);
  }, 720);
}

export { smoke };

